/** @import * as CPUProfileDataModel from '@paulirish/trace_engine/models/cpu_profile/CPUProfileDataModel.js' */
/** @import * as Protocol from '@paulirish/trace_engine/generated/protocol.js' */

import {toMicrosec} from './trace/trace.js';

// 3 decimal places. We don't need floating point decimal BS
/** @param {number} num */
const roundOff = num => Math.floor(num * 1000) / 1000;

/**
 * @param {JSSelfProfiling.ProfilerTrace} selfProfile
 * @return {{nodes: CPUProfileDataModel.ExtendedProfileNode[], _stackIdToNode: Map<number, CPUProfileDataModel.ExtendedProfileNode>, programNode: CPUProfileDataModel.ExtendedProfileNode, idleNode: CPUProfileDataModel.ExtendedProfileNode}}
 */
function buildNodes(selfProfile) {
  /** @type {CPUProfileDataModel.ExtendedProfileNode[]} */
  const nodes = []; // Each node is (typically) a single callframe along with its parent
  const _stackIdToNode = new Map();

  const scriptId0 = /** @type {Protocol.Runtime.ScriptId} */ ('0');

  const rootNode = {callFrame: {codeType: 'other', functionName: '(root)', scriptId: scriptId0}, id: 1};
  const programNode = {
    callFrame: {codeType: 'other', functionName: '(program)', scriptId: scriptId0},
    id: 2,
    parent: 1,
  };
  const idleNode = {callFrame: {codeType: 'other', functionName: '(idle)', scriptId: scriptId0}, id: 3, parent: 1};

  // @ts-expect-error missing lineNumber, etc.
  nodes.push(rootNode, programNode, idleNode);
  const nodeIdOffset = nodes.length + 1;

  selfProfile.stacks.forEach((stack, stackId) => {
    const frame = selfProfile.frames[stack.frameId];

    /** @type {CPUProfileDataModel.ExtendedProfileNode} */
    const node = {
      callFrame: {
        // @ts-expect-error protocol types are missing codeType attribute
        codeType: 'JS',
        functionName: frame.name,
      },
      id: stackId + nodeIdOffset,
    };

    if ('column' in frame) node.callFrame.columnNumber = frame.column - 1;
    if ('line' in frame) node.callFrame.lineNumber = frame.line - 1;

    if (typeof frame.resourceId !== 'undefined') {
      node.callFrame.url = selfProfile.resources[frame.resourceId];
      node.callFrame.scriptId = /** @type {Protocol.Runtime.ScriptId} */ (`${frame.resourceId + 200}`); // 0 gets special treatment. 200 is random, but no chance of offbyone
    } else {
      node.callFrame.scriptId = scriptId0;
    }

    _stackIdToNode.set(stackId, node);

    // Establish the parent.
    const parentStackId = stack.parentId; // parentId is a stackId of the parent. https://wicg.github.io/js-self-profiling/#dom-profilerstack-parentid:~:text=Let-,parentId,-be%20the%20result
    if (typeof parentStackId !== 'undefined') {
      const parentNode = _stackIdToNode.get(parentStackId);
      if (!parentNode) throw new Error('parents should have already been discovered…');
      node.parent = parentNode.id;
    } else {
      // Any nodes now without a parent are parented to the (root) node.
      node.parent = rootNode.id;
    }
    nodes.push(node);
  });

  return {
    nodes,
    _stackIdToNode,
    // @ts-expect-error missing lineNumber, etc.
    programNode,
    // @ts-expect-error missing lineNumber, etc.
    idleNode,
  };
}

/**
 * FYI Chrome source of the reverse (V8 Profile to selfProfile):
 * @see https://source.chromium.org/chromium/chromium/src/+/main:third_party/blink/renderer/bindings/core/v8/profiler_trace_builder.cc
 *
 * @param {JSSelfProfiling.ProfilerTrace} selfProfile
 * @returns {CPUProfileDataModel.ExtendedProfile}
 */
function selfProfileToCPUProfile(selfProfile) {
  const {nodes, idleNode, _stackIdToNode} = buildNodes(selfProfile);

  // From self profiling samples ==> CPU Profile Sample Nodes
  const samples = selfProfile.samples.map(samp => {
    // If there's no stack, it's either (idle) or (program). The latter is native operations (like Layout, Compile, etc).
    // We don't know which of the two it is, but.. it doesn't really matter. We call it idle.
    if (typeof samp.stackId === 'undefined') return idleNode.id;

    const matchingNode = _stackIdToNode.get(samp.stackId);
    if (!matchingNode) throw new Error('No stack match for sample');
    return matchingNode.id;
  });

  // "Time intervals between adjacent samples in microseconds. The first delta is relative to the profile startTime."
  const timeDeltas = selfProfile.samples.map((samp, i) => {
    if (i === 0) return roundOff(toMicrosec(samp.timestamp));

    const timeDeltaMs = samp.timestamp - selfProfile.samples[i - 1].timestamp;
    return roundOff(toMicrosec(timeDeltaMs));
  });

  const crdpProfile = {
    startTime: 0,
    endTime: toMicrosec(selfProfile.samples.reduce((acc, i) => (i.timestamp > acc ? i.timestamp : acc), 0)),
    nodes,
    samples,
    timeDeltas,
  };
  return crdpProfile;
}

export {selfProfileToCPUProfile};
