import {Types} from '@paulirish/trace_engine';

import {makeTraceEvent, μs, currentTrace} from './trace.js';

/** @import {FieldTrace}  from '../../../types/field-trace.js' */
/** @import {Page, Runtime} from '@paulirish/trace_engine/generated/protocol.js' */

/**
 *
 * @param {FieldTrace} fieldTrace
 */

export function enhanceWithSources(fieldTrace) {
  const {sources} = fieldTrace;
  if (!sources?.length) return;
  // TODO: scriptid should agree with same in cpuprofile/loaf.
  for (const source of sources || []) {
    const scriptCompiled = makeTraceEvent(source.isModule ? 'ModuleEvaluated' : 'ScriptCompiled', {
      cat: 'disabled-by-default-devtools.target-rundown',
      ts: μs(0),
      dur: μs(1),
      args: {
        data: {
          frame: /** @type {Page.FrameId} */ (source.frameId || '_frameid_'),
          frameType: source.frameType,
          url: source.url,
          isolate: '0x1',
          v8context: '0x1',
          origin: '<origin>', // this ok?
          scriptId: source.scriptId,
        },
      },
    });
    const sourceRundown = makeTraceEvent('ScriptCatchup', {
      cat: 'disabled-by-default-devtools.v8-source-rundown',
      ts: μs(0),
      dur: μs(1),
      args: {
        data: {
          isolate: '0x1',
          executionContextId: /** @type {Runtime.ExecutionContextId} */ (1),
          isModule: source.isModule,
          hasSourceUrl: source.hasSourceUrl,
          url: source.url,
          hash: undefined,
          sourceUrl: source.sourceUrl,
          sourceMapUrl: source.sourceMapUrl,
          scriptId: source.scriptId,
        },
      },
    });
    const rundownSourceText = makeTraceEvent('ScriptCatchup', {
      cat: 'disabled-by-default-devtools.v8-source-rundown-sources',
      ts: μs(0),
      dur: μs(1),
      args: {
        data: {
          isolate: 0x1,
          scriptId: source.scriptId,
          length: source.content?.length,
          sourceText: source.content,
        },
      },
    });
    currentTrace.push(scriptCompiled, sourceRundown, rundownSourceText);
  }

  const scriptIdByUrl = new Map(sources.map(source => [source.url, source.scriptId]));

  // LoAF created these with placeholder IDs. Match their URL to a captured
  // source, using the string ID required by FunctionCall and the numeric ID
  // used in ProfileCall's callFrame.
  for (const evt of currentTrace) {
    if (evt.name === Types.Events.Name.FUNCTION_CALL && evt.ph === Types.Events.Phase.COMPLETE) {
      const data = /** @type {Types.Events.FunctionCall} */ (evt).args.data;
      if (data?.url !== undefined) {
        const scriptId = scriptIdByUrl.get(data.url);
        if (scriptId !== undefined) data.scriptId = String(scriptId);
      }
    }

    // Synthetic ProfileCall has no runtime type guard, so check the callFrame
    // before changing its numeric scriptId.
    if (
      evt.name === 'ProfileCall' &&
      'callFrame' in evt &&
      evt.callFrame &&
      typeof evt.callFrame === 'object' &&
      'scriptId' in evt.callFrame &&
      'url' in evt.callFrame &&
      typeof evt.callFrame.url === 'string'
    ) {
      const scriptId = scriptIdByUrl.get(evt.callFrame.url);
      if (scriptId !== undefined) evt.callFrame.scriptId = scriptId;
    }
  }

  //  TODO:also handle profilechunks
  // const profileChunk = currentTrace.find(e => e.name === 'ProfileChunk');
}
